/**
 * R-112 / enterprise D2: the organization name (`organizations.organization_name`, API
 * `organizationName`). The API decides (422 organization_name_invalid / organization_name_blocked);
 * these helpers only label and pre-check, as the app does. Private: host Profile and CMS only (D3).
 */
export const ORGANIZATION_NAME_MIN = 3
export const ORGANIZATION_NAME_MAX = 60

const GENERATED_SUFFIX = "'s Gym Business"

/** The name as the host typed it; '' for an empty draft or a name generated by app builds up to 25. */
export function typedOrganizationName(stored?: string | null): string {
  const name = (stored ?? '').trim()
  if (!name || name.endsWith(GENERATED_SUFFIX)) return ''
  return name
}

/**
 * What an admin list or page shows as the organization's name: the stored name, else the first
 * business name of a draft that has no organization name yet.
 */
export function organizationDisplayName(t: { organizationName?: string | null; firstBusinessName?: string | null }): string {
  return (t.organizationName ?? '').trim() || (t.firstBusinessName ?? '').trim() || 'No organization name yet'
}

/** The first business name under the organization name when it adds something. */
export function firstBusinessSubName(t: { organizationName?: string | null; firstBusinessName?: string | null }): string | null {
  const org = (t.organizationName ?? '').trim()
  const business = (t.firstBusinessName ?? '').trim()
  if (!org || !business || business.toLowerCase() === org.toLowerCase()) return null
  return business
}
